-- =========================================================================
-- FAKE DATA SCRIPT: 50 Companies (Customer/Supplier) & 100 Contacts
-- Note: Bảng trong DB chuẩn của hệ thống có tên là "company" và "contact".
-- Nếu bạn muốn nạp vào bảng khác (vd: "companny" nếu viết sai chính tả), 
-- vui lòng thay thế chữ "public.company" thành "public.companny" bên dưới.
-- =========================================================================

-- 1. INSERT 50 COMPANIES
ON CONFLICT (company_id) DO UPDATE SET
  company_shortname = EXCLUDED.company_shortname,
  company_fullname = EXCLUDED.company_fullname,
  type = EXCLUDED.type,
  website = EXCLUDED.website,
  address = EXCLUDED.address,
  country = EXCLUDED.country,
  city = EXCLUDED.city;

-- 2. INSERT 100 CONTACTS (2 contacts per company)
ON CONFLICT (contact_id) DO UPDATE SET
  name = EXCLUDED.name,
  title = EXCLUDED.title,
  email = EXCLUDED.email,
  mobile_no = EXCLUDED.mobile_no,
  gen = EXCLUDED.gen,
  birthday = EXCLUDED.birthday,
  company_id = EXCLUDED.company_id;
